UPDATE google_places_types_staging
SET orden_tipo = orden_tipo + 9
WHERE categoria_codigo = 'food_and_drink'
  AND orden_tipo >= 131
  AND codigo_google NOT IN (
      'peruvian_restaurant', 'pizza_delivery', 'pizza_restaurant',
      'polish_restaurant', 'portuguese_restaurant', 'pub',
      'ramen_restaurant', 'restaurant', 'romanian_restaurant'
  );

DO $validation$
DECLARE
    row_count integer;
    unique_code_count integer;
    invalid_count integer;
BEGIN
    SELECT count(*), count(DISTINCT codigo_google)
    INTO row_count, unique_code_count
    FROM google_places_types_staging;

    SELECT count(*)
    INTO invalid_count
    FROM google_places_types_staging
    WHERE tabla_google <> 'A'
       OR btrim(codigo_google) = ''
       OR btrim(nombre_es) = ''
       OR btrim(categoria_codigo) = '';

    IF row_count <> 478 OR unique_code_count <> 478 OR invalid_count <> 0 THEN
        RAISE EXCEPTION 'Catálogo inválido: filas=%, códigos únicos=%, inválidas=%',
            row_count, unique_code_count, invalid_count;
    END IF;
END;
$validation$;

TRUNCATE TABLE public.google_places_types RESTART IDENTITY;

INSERT INTO public.google_places_types (
    categoria_codigo, categoria_nombre_en, categoria_nombre_es,
    codigo_google, nombre_en, nombre_es, agregado_en_google,
    tabla_google, fuente_url, version_catalogo,
    restriccion_en, restriccion_es, orden_categoria, orden_tipo
)
SELECT
    categoria_codigo, categoria_nombre_en, categoria_nombre_es,
    codigo_google, nombre_en, nombre_es, agregado_en_google,
    tabla_google, fuente_url, version_catalogo,
    restriccion_en, restriccion_es, orden_categoria, orden_tipo
FROM google_places_types_staging
ORDER BY orden_categoria, orden_tipo;

COMMIT;
